import{_ as o,o as r,c as n,ag as l}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"合同关键信息提取：把法律文本的\\"信息囚徒\\"解放出来","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/entrepreneurship/04-contract-key-extraction.md","filePath":"topics/entrepreneurship/04-contract-key-extraction.md"}'),s={name:"topics/entrepreneurship/04-contract-key-extraction.md"};function a(i,t,u,e,q,g){return r(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="合同关键信息提取-把法律文本的-信息囚徒-解放出来" tabindex="-1">合同关键信息提取：把法律文本的&quot;信息囚徒&quot;解放出来 <a class="header-anchor" href="#合同关键信息提取-把法律文本的-信息囚徒-解放出来" aria-label="Permalink to &quot;合同关键信息提取：把法律文本的&quot;信息囚徒&quot;解放出来&quot;">​</a></h1><h2 id="本质逻辑" tabindex="-1">本质逻辑 <a class="header-anchor" href="#本质逻辑" aria-label="Permalink to &quot;本质逻辑&quot;">​</a></h2><p>任何签过合同的人都知道那个痛：合同签完就扔进文件夹，直到付款日到了才想起来要看一眼。<strong>绝大多数合同的关键信息——付款日、续约日、违约责任、终止条款——都被埋没在几万字的法律文本里</strong>。</p><p>合同关键信息提取服务的本质，是<strong>用 AI + 标准化模板，把&quot;读合同&quot;这件专业律师才做的事，转化成一个普通人都能用的&quot;合同管家&quot;</strong>。你不提供法律意见，你提供&quot;结构化提醒&quot;。</p><p><strong>底层规律有四条</strong>：</p><p>第一，<strong>合同的真正价值不在签的那一刻，而在执行的每一天</strong>。一份合同 90% 的法律风险来自&quot;忘了某个日期&quot;、&quot;错过某个条款&quot;——这些事用 AI 提取 + 提醒就能解决 80%。</p><p>第二，<strong>绝大多数中小企业不雇法务</strong>。中国 4000 万中小企业，95% 没有专职法务。律师按小时计费（500–2000 元/小时）太贵，但他们其实需要的不是&quot;法律咨询&quot;，而是&quot;信息管理&quot;——这是低悬的果实。</p><p>第三，<strong>LLM 对结构化提取的天然能力</strong>。ChatGPT / Claude 对合同条款的分类、提取、总结，能力远超一般人。把 100 页合同变成 2 页关键节点清单，过去需要律师 4 小时，现在 AI 5 分钟。</p><p>第四，<strong>订阅模型的天然适配</strong>。合同管理不是一次性需求，是&quot;持续服务&quot;——你提取完，还要持续提醒、续约、归档。这是典型的 SaaS 业务。</p><h2 id="启动步骤" tabindex="-1">启动步骤 <a class="header-anchor" href="#启动步骤" aria-label="Permalink to &quot;启动步骤&quot;">​</a></h2><p><strong>第一步：选客户</strong>。两类：</p><ul><li><strong>中小企业主</strong>（10–100 人规模，年合同 50–500 份）</li><li><strong>自由职业者 / 工作室</strong>（设计、自媒体、咨询师，年合同 10–30 份）</li></ul><p>第二类起步最稳——他们自己就是客户，谈&quot;个人合同管家&quot;很轻。</p><p><strong>第二步：核心工具链</strong>。</p><ul><li><strong>文档处理</strong>：PyMuPDF、pdfplumber（PDF 转文本）</li><li><strong>AI 提取</strong>：ChatGPT API（gpt-4o-mini）、Claude API、DeepSeek、通义千问长文本</li><li><strong>结构化输出</strong>：用 Pydantic 定义合同 schema（甲方/乙方/金额/付款日/续约日/违约条款/终止条款）</li><li><strong>存储</strong>：Airtable / 飞书多维表格 / Notion Database</li><li><strong>提醒</strong>：企业微信/钉钉/飞书机器人 + 邮件 + 短信</li><li><strong>前端</strong>（如做 SaaS）：Next.js + Tailwind + Supabase</li></ul><p><strong>第三步：标准服务流程</strong>。</p><ol><li>客户上传合同（PDF/Word/图片扫描件）</li><li>AI 自动 OCR + 文本提取</li><li>按 schema 抽取关键字段 + 风险条款</li><li>生成&quot;合同摘要&quot;（1 页 A4）</li><li>自动同步到客户日历/提醒工具</li><li>重要日期前 7/3/1 天自动提醒</li></ol><p><strong>第四步：交付物</strong>。</p><ul><li>单次提取：50–200 元/份</li><li>月度套餐：99–299 元/月（5–20 份）</li><li>年度订阅：999–2999 元/年（无限份 + 持续提醒）</li></ul><p><strong>第五步：合规</strong>。明确声明&quot;不提供法律意见，所有信息以原文为准&quot;。让客户签&quot;数据使用授权&quot;协议。涉及隐私条款的合同，单独走加密流程。</p><p><strong>第六步：MVP 启动</strong>。前 3 个月用 ChatGPT + Airtable + 飞书机器人手工跑通流程，<strong>不要急着做 SaaS</strong>。验证&quot;客户愿不愿意为这个付月费&quot;再投入开发。</p><h2 id="收入模型" tabindex="-1">收入模型 <a class="header-anchor" href="#收入模型" aria-label="Permalink to &quot;收入模型&quot;">​</a></h2><p><strong>核心收入：年度订阅</strong>。</p><ul><li>30 个个人订阅 × 999 元 = 29970 元</li><li>20 个小微企业订阅 × 2999 元 = 59980 元</li><li><strong>年收入约 9 万元（单兵）</strong></li></ul><p><strong>辅助收入</strong>：</p><ul><li>单次合同审查（律师审核）转介绍抽佣 10–20%</li><li>合同模板销售（劳动/采购/服务/租赁模板包，99–499 元）</li><li>行业定制（针对电商、教育、医疗做&quot;行业合同库&quot;）</li></ul><p><strong>毛利率</strong>：</p><ul><li>AI API 成本：约 0.1–0.5 元/份</li><li>存储 + 工具订阅：50–200 元/月</li><li><strong>毛利率 85%–95%</strong></li></ul><p><strong>回本周期</strong>：1–2 个月（基本零成本启动）。</p><h2 id="获客方法" tabindex="-1">获客方法 <a class="header-anchor" href="#获客方法" aria-label="Permalink to &quot;获客方法&quot;">​</a></h2><p><strong>冷启动期（0–10 客户）</strong>：</p><ul><li>朋友圈&quot;案例展示&quot;：发&quot;我帮 XX 老板整理了 12 份合同，发现 3 个被遗忘的付款节点&quot;</li><li>法务社群、HR 社群分享&quot;AI 提取合同&quot;工作流</li><li>小红书/知乎写&quot;打工人合同避坑指南&quot;，引流到私域</li><li>律师/会计师事务所合作：你做&quot;前端信息提取&quot;，他们做&quot;后端法律咨询&quot;，互推</li></ul><p><strong>成长期（10–50 客户）</strong>：</p><ul><li>内容 IP：抖音/视频号&quot;合同冷知识&quot;系列（每集讲 1 个真实合同案例）</li><li>行业 KOL 合作：HR 博主、创业博主</li><li>私域社群运营：每周 1 次&quot;合同避坑&quot;直播</li><li>工具平台分销：与飞书/钉钉应用市场合作</li></ul><p><strong>成熟期（50+ 客户）</strong>：</p><ul><li>SaaS 化产品（99 元/月起步）</li><li>B 端销售：直接对接企业法务部、IT 部</li><li>行业白皮书：&quot;2026 年中小企业合同风险报告&quot;</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><p><strong>坑一：合规风险</strong>。<strong>这是这门生意的命门</strong>。你必须严格声明&quot;不提供法律意见&quot;，所有提取结果由用户自行确认。否则就是无证执业，分分钟被告。</p><p><strong>坑二：AI 提取错误</strong>。LLM 偶尔会读错数字、搞混当事人。必须建立&quot;人工抽检&quot;机制，前 100 份 100% 人工复核。</p><p><strong>坑三：客户期望管理</strong>。用户会问&quot;这份合同能签吗&quot;、&quot;这条款对我公平吗&quot;——必须挡回去，&quot;我们只做提取和提醒，不做判断&quot;。</p><p><strong>坑四：合同多样性</strong>。中国合同有 N 种格式（中文/英文/双语/扫描件/手写件），AI 处理能力有上限。扫描件要 OCR，手写件几乎无法处理，要在交付前说清楚。</p><p><strong>坑五：数据安全</strong>。合同是最敏感的商业数据。用第三方云存储要谨慎，最好用&quot;客户自管数据&quot;模式（数据存客户自己空间，你只提供提取 API）。</p><p><strong>坑六：律师打压</strong>。律师协会对&quot;AI 替代法律服务&quot;很敏感。要避免用&quot;智能法务&quot;、&quot;AI 律师&quot;等措辞，改用&quot;合同管家&quot;、&quot;合同助手&quot;等中性感性词。</p><p><strong>坑七：续费率低</strong>。提醒 1 次之后客户就忘了&quot;原来还有这个服务&quot;。要做&quot;持续触达&quot;——每月发&quot;您的合同管家月报&quot;，包含当月到期、待续约、待审阅合同清单。</p><h2 id="规模化路径" tabindex="-1">规模化路径 <a class="header-anchor" href="#规模化路径" aria-label="Permalink to &quot;规模化路径&quot;">​</a></h2><p><strong>阶段一：单兵服务</strong>（0–6 月）。1 人，纯手工 + AI 工具，月 30 客户，月入 1–2 万。</p><p><strong>阶段二：半自动化</strong>（6–12 月）。搭建半自动工作流（API + 模板 + 提醒），月 100 客户，月入 3–5 万。</p><p><strong>阶段三：SaaS 化</strong>（1–2 年）。把工作流打包成&quot;合同管家 SaaS&quot;，99–499 元/月自助订阅。技术投入 5–10 万。</p><p><strong>阶段四：垂直深耕</strong>（2+ 年）。专注 1–2 个行业（电商合同、建筑合同、教培合同），做&quot;行业合同标准库 + 风险规则引擎&quot;，单客单价 5000+。</p><p><strong>阶段五：生态合作</strong>（可选）。与飞书、钉钉、企业微信深度集成，成为它们的&quot;合同模块&quot;官方合作伙伴，按调用抽佣。</p><p><strong>最终形态</strong>：中国版 Ironclad（合同生命周期管理 SaaS 公司，市值 30+ 亿美元）的简化版 + 本地化版。<strong>0 起步、技术轻、可持续订阅，3 年做到年收入 100–500 万元</strong>。但要走得远，必须死守&quot;信息提取不碰法律判断&quot;的边界。</p>',51)])])}const h=o(s,[["render",a]]);export{c as __pageData,h as default};
